        "script": "var body = $vars.fetchWeather1.output.body;\nvar current = body.current;\nvar temp = current.temperature_2m;\nvar weatherCode = current.weathercode;\nvar windSpeed = current.windspeed_10m;\nvar precipitation = current.precipitation;\nvar isNiceTemp = temp >= 60 && temp <= 85;\nvar isNiceWeather = weatherCode <= 2;\nvar isNiceWind = windSpeed < 15;\nvar isNicePrecip = precipitation === 0;\nvar isNiceDay = isNiceTemp && isNiceWeather && isNiceWind && isNicePrecip;\nvar verdict;\nif (isNiceDay) {\n  verdict = 'Yes! It is a beautiful day in Bellevue! Get outside!';\n} else {\n  var reasons = [];\n  if (!isNiceTemp) { reasons.push('Temperature is ' + temp + 'F (ideal: 60-85F)'); }\n  if (!isNiceWeather) { reasons.push('Not clear sky, weather code: ' + weatherCode); }\n  if (!isNiceWind) { reasons.push('Wind is ' + windSpeed + ' mph (ideal: under 15 mph)'); }\n  if (!isNicePrecip) { reasons.push('Precipitation: ' + precipitation + ' inches'); }\n  verdict = 'Not the nicest day. ' + reasons.join('; ');\n}\nreturn { isNiceDay: isNiceDay, verdict: verdict, temperature_f: temp, weatherCode: weatherCode, windSpeed_mph: windSpeed, precipitation_in: precipitation };"
